class Solution:
     def findLongestWord(self, s, d):
         """
         :type s: str
         :type d: List[str]
         :rtype: str
         """
         result = ''
         for word in d:
             lo = 0
             for l in word:
                 lo = s.find(l, lo)+1
                 if lo == 0:
                     break
             if lo > 0 and len(word) >= len(result):
                 if len(word) == len(result):
                     result = word if word < result else result
                 else:
                     result = word
         return result

from collections import Counter

def get_key_length(cipher_text, max_key_length):
    avg_IC_by_keylen = {}

    for key_len in range(1, max_key_length+1):
        ICs = []

        for i in range(key_len):
            sub_str = cipher_text[i::key_len]
            freq = Counter(sub_str)
            IC = sum(v * (v-1) for k, v in freq.items()) / (len(sub_str) *  (len(sub_str)-1) )
            ICs.append(IC)

        avg_IC_by_keylen[key_len] = sum(ICs) / key_len

    return max(avg_IC_by_keylen, key=avg_IC_by_keylen.get)

def balanced_parens(n): return list(dfs([],0,0,n))

def dfs(s, open, close, maxP):
    if close==maxP:
        yield "".join(s)
        return

    if open > close:
        s.append(')')
        yield from dfs(s,open,close+1,maxP)
        s.pop()

    if open < maxP:
        s.append('(')
        yield from dfs(s,open+1,close,maxP)
        s.pop()

