class Solution:
    def containsCycle(self, grid: List[List[str]]) -> bool:
        n = len(grid)
        m = len(grid[0])

        F = [i for i in range(m * n)]
        def find(x):
            if x == F[x]:
                return x
            else:
                F[x] = find(F[x])
                return F[x]

        for i in range(n):
            for j in range(m):
                if i > 0 and grid[i-1][j] == grid[i][j]:
                    f1 = find((i-1)*m+j)
                    f2 = find((i)*m+j)
                    if f1 == f2:
                        return True
                    F[f1] = f2
                if j > 0 and grid[i][j-1] == grid[i][j]:
                    f1 = find((i)*m+j-1)
                    f2 = find((i)*m+j)
                    if f1 == f2:
                        return True
                    F[f1] = f2
        return False

class Solution:
     def getSum(self, a, b):
         max = 0x7FFFFFFF
         mask = 0xFFFFFFFF
         while b != 0:
             a, b = (a ^ b) & mask, ((a & b) << 1) & mask
         return a if a <= max else ~(a ^ mask)

def prod2sum(a, b, c, d):
    e = sorted([abs(a*d-b*c), abs(a*c+b*d)])
    f = sorted([abs(a*c-b*d), abs(a*d+b*c)])
    if e == f:
        return [e]
