def primef(n):
    i= 2; f= []
    while i*i<=n:
        if n%i: i+=1
        else: n//=i; f.append(i)
    if n>1: f.append(n)
    return f

def count_zeros_n_double_fact(n): 
    if n % 2 != 0:
        return 0
    k = 0
    while n >= 10:
        k += n // 10
        n //= 5
    return k

