def dec2FactString(nb):
    ret = []
    for f in reversed(FACTORIALS):
        (d, nb) = divmod(nb, f)
        if d or ret:
            ret.append(DIGITS[d])
    return ''.join(ret)

def factString2Dec(string):
    return sum(DIGITS.index(d) * f for (d, f) in zip(reversed(string), FACTORIALS))

def check_root(string):
    try:
        a,b,c,d = [int(i) for i in string.split(',')]
        if not (a == b-1 and a == c-2 and a == d-3):
            return 'not consecutive'
        s = a*b*c*d+1
        return str(s)+', '+str(int(s**0.5))
    except:
        return 'incorrect input'

def dot(n, m):
    sep = '+---' * n + '+'
    dot = '| o ' * n + '|'
    return '\n'.join([sep, dot] * m + [sep])

def get_count(words=""):
    if not isinstance(words, str):
        return {'vowels':0,'consonants':0}
    letter = "".join([c.lower() for c in words if c.isalpha()])
    vowel = "".join([c for c in letter if c in 'aeiou'])
    consonant = "".join([c for c in letter if c not in 'aeiou']) 
