class Solution:
    def findBestValue(self, arr: List[int], target: int) -> int:
        arr.sort()
        n = len(arr)
        for i in range(n):
            sol = round(target / n)
            if arr[i] >= sol:
                return sol
            target -= arr[i]
            n -= 1
        return arr[-1]

def naughty_or_nice(data):
    nice = 0
    for month in data:
        for day in data[month]:
            nice += 1 if data[month][day] == "Nice" else -1
    return "Nice!" if nice >= 0 else "Naughty!"

